    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>আগের পাঠে প্রতিটি token নিজের সাথেই সবচেয়ে বেশি মিলেছে, আর “কী খুঁজছি” ও “কী দিতে পারি” একই vector। ধরুন “হার” শব্দটি চায় তার আগের বিশেষণ খুঁজতে—নিজেকে নয়। আর ৫১২-dimension vector-এর dot product বিশাল হতে পারে; softmax তখন একটিকে ১ আর বাকি সব ০ দেবে। দুটো সমস্যার সমাধান কী?</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>Q, K, V, score, weight ও আউটপুটের shape লিখতে পারবেন</li><li>scaled dot-product attention কোডে হিসাব করতে পারবেন</li><li>কেন √d_k দিয়ে ভাগ করা হয় তা সংখ্যাগতভাবে দেখাতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 45 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/why-attention/">কেন Attention: প্রসঙ্গ-নির্ভর অর্থ</a></li><li><a href="/ai-academy/lesson/matrix-shape/">Matrix, Shape ও Matrix Multiplication</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><div class="wgba-table-wrap"><table><caption>scaled dot-product attention</caption><thead><tr><th scope="col">ধাপ</th><th scope="col">হিসাব</th><th scope="col">shape (n = ৩, d = ৪, d_k = d_v = ২)</th></tr></thead><tbody><tr><td>ইনপুট</td><td>X</td><td>৩ × ৪</td></tr><tr><td>Query/Key/Value</td><td>Q = XW_Q, K = XW_K, V = XW_V</td><td>W: ৪ × ২ → Q, K, V: ৩ × ২</td></tr><tr><td>Score</td><td>S = QKᵀ / √d_k</td><td>৩ × ২ · ২ × ৩ = ৩ × ৩</td></tr><tr><td>Weight</td><td>A = softmax(S), প্রতি সারিতে</td><td>৩ × ৩, প্রতি সারির যোগ ১</td></tr><tr><td>আউটপুট</td><td>Y = AV</td><td>৩ × ৩ · ৩ × ২ = ৩ × ২</td></tr></tbody></table></div><p><strong>কেন আলাদা Q ও K:</strong> W_Q ও W_K ভিন্ন হলে qᵢ · kⱼ প্রতিসম নয়—“হার” “গলার”-কে খুঁজতে পারে, কিন্তু “গলার” “হার”-কে একই মাত্রায় খুঁজতে বাধ্য নয়। নিজের সাথে মিলও আর স্বয়ংক্রিয়ভাবে সর্বোচ্চ নয়।</p><p><strong>কেন V আলাদা:</strong> কাকে দেখব (Q·K) আর কী তথ্য নেব (V) আলাদা শেখা যায়।</p><p><strong>কেন √d_k:</strong> q ও k-এর উপাদানগুলো স্বাধীন, গড় ০ ও variance ১ হলে q · k-এর variance = d_k। d_k = ৬৪-এ standard deviation ৮—score প্রায়ই ±১৬, softmax প্রায় one-hot। √d_k দিয়ে ভাগ করলে variance আবার ১।</p></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> লাইব্রেরিতে আপনার প্রশ্ন (Query) প্রতিটি বইয়ের ক্যাটালগ-কার্ডের (Key) সাথে মেলানো হয়; যত ভালো মিল, সেই বইয়ের বিষয়বস্তু (Value) থেকে তত বেশি নেওয়া হয়।</p><p><strong>কোথায় ভাঙে:</strong> লাইব্রেরিতে কার্ড আর বই আলাদা জিনিস যা মানুষ লেখে; attention-এ Q, K, V একই token থেকে তিনটি শেখা রূপান্তর—কার্ডে কী লেখা থাকবে তা training ঠিক করে।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>d_k = ২, q = [১, ০], k₁ = [১, ০], k₂ = [০, ১], v₁ = [১০, ০], v₂ = [০, ১০]।</p><ol><li>score = [১, ০] / √২ ≈ [০.৭০৭, ০]।</li><li>softmax ≈ [০.৬৭০, ০.৩৩০]।</li><li>আউটপুট ≈ ০.৬৭ × [১০, ০] + ০.৩৩ × [০, ১০] = [৬.৭০, ৩.৩০]।</li><li>√২ দিয়ে ভাগ না করলে: softmax([১, ০]) ≈ [০.৭৩১, ০.২৬৯]—একটু বেশি তীক্ষ্ণ।</li></ol></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><div class="wgba-note">কোডে matmul/transpose/softmax সহায়ক, একটি attention ফাংশন যা প্রতিটি ধাপের shape মুদ্রণ করে, এবং d_k বাড়ালে scaled বনাম unscaled softmax-এর সর্বোচ্চ weight।</div><h3>scaled dot-product attention ও √d পরীক্ষা</h3><div class="wgba-playground-slot" data-exercise="ex-les-08-02-qkv-scaled-1"><pre class="wgba-code"><code>function makeRng(seed) { let a = seed &gt;&gt;&gt; 0; return function () { a = (a + 0x6D2B79F5) &gt;&gt;&gt; 0; let t = a; t = Math.imul(t ^ (t &gt;&gt;&gt; 15), t | 1); t ^= t + Math.imul(t ^ (t &gt;&gt;&gt; 7), t | 61); return ((t ^ (t &gt;&gt;&gt; 14)) &gt;&gt;&gt; 0) / 4294967296; }; }
const r3 = (x) =&gt; Math.round(x * 1000) / 1000;
const matmul = (A, B) =&gt; {
  if (A[0].length !== B.length) throw new Error(&quot;shape মেলেনি: &quot; + A.length + &quot;×&quot; + A[0].length + &quot; · &quot; + B.length + &quot;×&quot; + B[0].length);
  return A.map((row) =&gt; B[0].map((_, j) =&gt; row.reduce((s, v, k) =&gt; s + v * B[k][j], 0)));
};
const T = (M) =&gt; M[0].map((_, j) =&gt; M.map((row) =&gt; row[j]));
const shape = (M) =&gt; M.length + &quot;×&quot; + M[0].length;
function softmaxRow(z) {
  const m = Math.max(...z);
  if (m === -Infinity) throw new Error(&quot;সব মান -Infinity: softmax অসংজ্ঞায়িত&quot;);
  const e = z.map((v) =&gt; Math.exp(v - m));
  const s = e.reduce((a, b) =&gt; a + b, 0);
  return e.map((v) =&gt; v / s);
}
const fmt = (M) =&gt; M.map((r) =&gt; r.map(r3));

function attention(X, WQ, WK, WV, log = false) {
  const Q = matmul(X, WQ), K = matmul(X, WK), V = matmul(X, WV);
  const dk = K[0].length;
  const S = matmul(Q, T(K)).map((r) =&gt; r.map((v) =&gt; v / Math.sqrt(dk)));
  const A = S.map(softmaxRow);
  const Y = matmul(A, V);
  if (log) console.log(&quot;shape → X&quot;, shape(X), &quot;| Q&quot;, shape(Q), &quot;| K&quot;, shape(K), &quot;| V&quot;, shape(V), &quot;| S&quot;, shape(S), &quot;| A&quot;, shape(A), &quot;| Y&quot;, shape(Y));
  return { Q, K, V, S, A, Y };
}

const X = [[1, 0, 1, 0], [0, 1, 0, 1], [1, 1, 0, 0]];   // 3 token, d = 4
const WQ = [[1, 0], [0, 1], [1, 0], [0, 0]], WK = [[0, 1], [1, 0], [0, 0], [1, 1]], WV = [[1, 0], [0, 1], [1, 1], [0, 0]];
const r = attention(X, WQ, WK, WV, true);
console.log(&quot;A =&quot;, JSON.stringify(fmt(r.A)));
console.log(&quot;সারির যোগ:&quot;, r.A.map((row) =&gt; r3(row.reduce((a, b) =&gt; a + b, 0))));
console.log(&quot;Y =&quot;, JSON.stringify(fmt(r.Y)));

// worked উদাহরণ
const w = softmaxRow([1 / Math.sqrt(2), 0]);
console.log(&quot;worked: weight&quot;, w.map(r3), &quot;আউটপুট&quot;, [10 * w[0], 10 * w[1]].map(r3));

// d_k বাড়লে: দৈব q, k (গড় 0, variance ~1)
const rand = makeRng(5), gauss = () =&gt; { let s = 0; for (let i = 0; i &lt; 12; i++) s += rand(); return s - 6; };
for (const dk of [4, 64, 512]) {
  let maxScaled = 0, maxRaw = 0; const trials = 40;
  for (let t = 0; t &lt; trials; t++) {
    const q = Array.from({ length: dk }, gauss), keys = Array.from({ length: 8 }, () =&gt; Array.from({ length: dk }, gauss));
    const raw = keys.map((k) =&gt; k.reduce((s, v, i) =&gt; s + v * q[i], 0));
    maxRaw += Math.max(...softmaxRow(raw)) / trials;
    maxScaled += Math.max(...softmaxRow(raw.map((v) =&gt; v / Math.sqrt(dk)))) / trials;
  }
  console.log(&quot;d_k=&quot; + String(dk).padEnd(4), &quot;গড় সর্বোচ্চ weight (8 key): √d ছাড়া&quot;, r3(maxRaw), &quot;| √d দিয়ে&quot;, r3(maxScaled));
}</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>matmul</code> শুরুতে shape যাচাই করে—ভুল shape-এ স্পষ্ট বার্তা।</li><li><code>T(K)</code>: transpose; QKᵀ-এর জন্য।</li><li><code>S.map(softmaxRow)</code>: প্রতিটি query-র সারিতে আলাদা softmax।</li><li>পরীক্ষা অংশ: একই দৈব score, একবার √d দিয়ে ভাগ করে, একবার ছাড়া—গড় সর্বোচ্চ weight তুলনা।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>W matrix হাতে বাছা হয়েছে (শেখা নয়) যাতে shape ও সংখ্যা অনুসরণ করা যায়। √d পরীক্ষা ৪০টি দৈব নমুনার গড়—একটি নমুনা দেখে “প্রায় one-hot” দাবি করা যেত না।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>Q = XW_Q, K = XW_K, V = XW_V</li><li>A = softmax(QKᵀ/√d_k), প্রতি সারিতে</li><li>Y = AV; shape n × d_v</li><li>√d_k: score-এর variance স্থির রাখে</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>attention-এর gradient</li><li>FlashAttention ও মেমরি-কৌশল</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>WK-কে WQ-এর সমান করুন। A-এর diagonal (নিজের সাথে weight) কি এখন বড় হলো? কেন আলাদা Q ও K রাখা কাজের?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>softmax কলাম ধরে করা (সারি নয়)</li><li>√d_k-এর বদলে d_k দিয়ে ভাগ</li><li>K-এর transpose ভুলে যাওয়া</li><li>V-এর shape আউটপুটের shape ঠিক করে—ভুলে যাওয়া</li></ul></section>
