const layerNorm = (X) =&gt; X.map((x) =&gt; { const m = x.reduce((a, b) =&gt; a + b, 0) / x.length; const v = x.reduce((s, t) =&gt; s + (t - m) ** 2, 0) / x.length; return x.map((t) =&gt; (t - m) / Math.sqrt(v + 1e-5)); });

function head(X, W, causal) {
