    'body_html' => '<section class="wgba-section" id="problem"><h2>সমস্যাটা কী?</h2><p>একটি লাইব্রেরি থেকে attention কোড নিলেন, ফল “ঠিক দেখাচ্ছে”। কিন্তু কীভাবে নিশ্চিত হবেন mask সত্যিই ভবিষ্যৎ ঢাকছে, বড় সংখ্যায় NaN হচ্ছে না, আর shape ভুল হলে চুপচাপ ভুল ফল আসছে না? একটি একক উদাহরণের আউটপুট দেখে এগুলো প্রমাণ হয় না—বৈশিষ্ট্য পরীক্ষা লাগে।</p></section>
<section class="wgba-section" id="objectives"><h2>শেখার লক্ষ্য</h2><ul><li>attention-এর প্রতিটি মধ্যবর্তী ধাপ পাঠযোগ্যভাবে দেখাতে পারবেন</li><li>attention implementation-এর জন্য বৈশিষ্ট্য-ভিত্তিক পরীক্ষা লিখতে পারবেন</li><li>weight টেবিল পড়ে কোন token কাকে দেখছে ব্যাখ্যা করতে পারবেন</li></ul><p class="wgba-meta">আনুমানিক সময়: 60 মিনিট</p></section>
<section class="wgba-section" id="prereq"><h2>পূর্বশর্ত</h2><ul><li><a href="/ai-academy/lesson/multi-head-transformer-block/">Multi-Head Attention ও Transformer Block</a></li></ul></section>
<section class="wgba-section" id="explain"><h2>ব্যাখ্যা</h2><p><strong>Calculator-এর ইন্টারফেস:</strong> <code>calc({ tokens, X, WQ, WK, WV, causal })</code> → { Q, K, V, S, Smasked, A, Y }। প্রতিটি ধাপ ফেরত দেওয়া হয় যাতে পরীক্ষা ও প্রদর্শন দুটোই সম্ভব।</p><div class="wgba-table-wrap"><table><caption>calculator-এর স্বয়ংক্রিয় পরীক্ষা</caption><thead><tr><th scope="col">বৈশিষ্ট্য</th><th scope="col">কেন</th><th scope="col">কীভাবে যাচাই</th></tr></thead><tbody><tr><td>সারির যোগ = ১</td><td>softmax-এর সংজ্ঞা</td><td>|Σⱼ Aᵢⱼ − ১| < ১০⁻¹²</td></tr><tr><td>mask-এ ঠিক ০</td><td>ভবিষ্যৎ leakage নেই</td><td>j > i ঘর === ০</td></tr><tr><td>বড় score-এ স্থিতিশীল</td><td>max বাদ না দিলে e^১০০০ = Infinity</td><td>score ১০০০ দিয়ে চালিয়ে isFinite</td></tr><tr><td>shape এরর</td><td>চুপচাপ ভুল ফল ঠেকানো</td><td>ভুল W দিয়ে চালালে exception</td></tr></tbody></table></div><p><strong>ASCII heat map:</strong> প্রতিটি weight-কে একটি অক্ষরে: “ ” (< ০.০৫), “.” (< ০.২), “o” (< ০.৪), “O” (< ০.৬), “@” (≥ ০.৬)। স্ক্রিন রিডারের জন্য সংখ্যার টেবিলও থাকে।</p><div class="wgba-note">উদাহরণের embedding ও W হাতে বাছা teaching মান। বাস্তব মডেলের attention weight দেখে “মডেল কেন এই সিদ্ধান্ত নিল” ব্যাখ্যা করা বিতর্কিত—attention weight সবসময় মডেলের যুক্তির বিশ্বস্ত ব্যাখ্যা নয় (সূত্র দেখুন)।</div></section>
<section class="wgba-section" id="analogy"><h2>উপমা — এবং কোথায় ভাঙে</h2><p><strong>উপমা:</strong> Calculator হলো একটি স্বচ্ছ ঘড়ি যার ভেতরের প্রতিটি চাকা দেখা যায়, সাথে একটি চেকলিস্ট যা প্রতিবার চালানোর পর নিশ্চিত করে কোনো চাকা উল্টো ঘুরছে না।</p><p><strong>কোথায় ভাঙে:</strong> ঘড়ির চাকা দেখে সময় কেন এমন তা পুরোপুরি বোঝা যায়; attention weight দেখে মডেলের “কারণ” পুরোপুরি বোঝা যায় না—শুধু একটি স্তরের একটি অংশ দেখা যায়।</p></section>
<section class="wgba-section" id="worked"><h2>ধাপে ধাপে উদাহরণ</h2><p>heat map পড়া: সারি = কে দেখছে (query), কলাম = কাকে দেখছে (key)। causal-এ উপরের ডান ত্রিভুজ ফাঁকা। শেষ সারি সবচেয়ে বেশি প্রসঙ্গ দেখে।</p></section>
<section class="wgba-section" id="activity"><h2>অনুশীলন / অ্যাক্টিভিটি</h2><p><strong>প্রজেক্ট মানদণ্ড:</strong> (১) “গলার সোনার হার সুন্দর” বাক্যে weight টেবিল ও heat map, (২) চারটি বৈশিষ্ট্য-পরীক্ষার পাস/ফেল রিপোর্ট, (৩) causal বন্ধ করে টেবিল তুলনা, (৪) “হার” কাকে সবচেয়ে বেশি দেখছে এবং কেন (teaching vector থেকে ব্যাখ্যা)।</p><h3>প্রজেক্ট: attention calculator ও বৈশিষ্ট্য-পরীক্ষা</h3><div class="wgba-playground-slot" data-exercise="ex-les-08-05-project-attention-calculator-1"><pre class="wgba-code"><code>const r3 = (x) =&gt; Math.round(x * 1000) / 1000;
const matmul = (A, B) =&gt; {
  if (A[0].length !== B.length) throw new Error(&quot;shape মেলেনি: &quot; + A.length + &quot;×&quot; + A[0].length + &quot; · &quot; + B.length + &quot;×&quot; + B[0].length);
  return A.map((row) =&gt; B[0].map((_, j) =&gt; row.reduce((s, v, k) =&gt; s + v * B[k][j], 0)));
};
const T = (M) =&gt; M[0].map((_, j) =&gt; M.map((row) =&gt; row[j]));
const shape = (M) =&gt; M.length + &quot;×&quot; + M[0].length;
function softmaxRow(z) {
  const m = Math.max(...z);
  if (m === -Infinity) throw new Error(&quot;সব মান -Infinity: softmax অসংজ্ঞায়িত&quot;);
  const e = z.map((v) =&gt; Math.exp(v - m));
  const s = e.reduce((a, b) =&gt; a + b, 0);
  return e.map((v) =&gt; v / s);
}
const fmt = (M) =&gt; M.map((r) =&gt; r.map(r3));

function calc({ tokens, X, WQ, WK, WV, causal = true }) {
  if (tokens.length !== X.length) throw new Error(&quot;token সংখ্যা (&quot; + tokens.length + &quot;) ≠ X-এর সারি (&quot; + X.length + &quot;)&quot;);
  const Q = matmul(X, WQ), K = matmul(X, WK), V = matmul(X, WV), dk = K[0].length;
  const S = matmul(Q, T(K)).map((r) =&gt; r.map((v) =&gt; v / Math.sqrt(dk)));
  const Smasked = S.map((r, i) =&gt; r.map((v, j) =&gt; (causal &amp;&amp; j &gt; i ? -Infinity : v)));
  const A = Smasked.map(softmaxRow);
  return { Q, K, V, S, Smasked, A, Y: matmul(A, V), tokens, causal };
}
function report(r) {
  console.log(&quot;shape: X &quot; + r.tokens.length + &quot;×&quot; + r.Q.length + &quot; → Q &quot; + shape(r.Q) + &quot;, K &quot; + shape(r.K) + &quot;, V &quot; + shape(r.V) + &quot;, A &quot; + shape(r.A) + &quot;, Y &quot; + shape(r.Y) + (r.causal ? &quot; (causal)&quot; : &quot;&quot;));
  const w = Math.max(...r.tokens.map((t) =&gt; t.length)) + 1;
  console.log(&quot;&quot;.padEnd(w) + r.tokens.map((t) =&gt; t.padStart(7)).join(&quot;&quot;));
  r.A.forEach((row, i) =&gt; console.log(r.tokens[i].padEnd(w) + row.map((v) =&gt; String(r3(v)).padStart(7)).join(&quot;&quot;)));
  const ch = (v) =&gt; (v &lt; 0.05 ? &quot; &quot; : v &lt; 0.2 ? &quot;.&quot; : v &lt; 0.4 ? &quot;o&quot; : v &lt; 0.6 ? &quot;O&quot; : &quot;@&quot;);
  console.log(&quot;heat map:&quot;); r.A.forEach((row, i) =&gt; console.log(&quot;  &quot; + r.tokens[i].padEnd(w) + &quot;|&quot; + row.map(ch).join(&quot;&quot;) + &quot;|&quot;));
}
function properties(r) {
  const res = {};
  res.rowSum = r.A.every((row) =&gt; Math.abs(row.reduce((a, b) =&gt; a + b, 0) - 1) &lt; 1e-12);
  res.maskZero = !r.causal || r.A.every((row, i) =&gt; row.every((v, j) =&gt; j &lt;= i || v === 0));
  const big = calc({ ...r.input, WQ: r.input.WQ.map((row) =&gt; row.map((v) =&gt; v * 1000)) });
  res.stableBig = big.A.flat().every(isFinite);
  try { calc({ ...r.input, WK: [[1, 0]] }); res.shapeError = false; } catch (e) { res.shapeError = true; }
  return res;
}

// teaching vector: [গয়না, ধাতু, রূপ, বিশেষ্য]
const tokens = [&quot;গলার&quot;, &quot;সোনার&quot;, &quot;হার&quot;, &quot;সুন্দর&quot;];
const X = [[0.8, 0, 0, 0.5], [0.3, 1, 0.2, 0], [1, 0.4, 0, 1], [0.2, 0, 1, 0]];
const WQ = [[1, 0], [0, 1], [0, 0], [1, 0]], WK = [[1, 0], [0, 1], [0.5, 0], [0, 0]], WV = [[1, 0], [0, 1], [0, 1], [0, 0]];
const input = { tokens, X, WQ, WK, WV, causal: true };
const r = calc(input); r.input = input;
report(r);
const props = properties(r);
console.log(&quot;বৈশিষ্ট্য-পরীক্ষা:&quot;, Object.entries(props).map(([k, v]) =&gt; k + &quot;=&quot; + (v ? &quot;পাস&quot; : &quot;ফেল&quot;)).join(&quot;, &quot;));
const i = tokens.indexOf(&quot;হার&quot;), top = r.A[i].indexOf(Math.max(...r.A[i]));
console.log(&quot;“হার” সবচেয়ে বেশি দেখছে:&quot;, tokens[top], &quot;(&quot; + r3(r.A[i][top]) + &quot;)&quot;);</code></pre><p class="wgba-meta">JavaScript চালু থাকলে এখানে Run বাটনসহ এডিটর আসবে।</p></div></section>
<details class="wgba-disclose"><summary>লাইন ধরে বুঝি</summary><div><ul><li><code>calc</code>: প্রতিটি মধ্যবর্তী ধাপ ফেরত দেয়; শুরুতে token-সংখ্যা যাচাই।</li><li><code>report</code>: token নামসহ টেবিল ও heat map—সংখ্যা ও চিত্র দুটোই।</li><li><code>properties</code>: চারটি বৈশিষ্ট্য; stableBig-এ W_Q ১০০০ গুণ করে score বিশাল করা হয়।</li><li><code>{ ...r.input, WK: [[1, 0]] }</code>: ইচ্ছাকৃত ভুল shape—exception আশা করা হয়।</li></ul></div></details>
<details class="wgba-disclose"><summary>এখানে এটা কেন ব্যবহার করেছি?</summary><div><p>বৈশিষ্ট্য-পরীক্ষাগুলো নির্দিষ্ট সংখ্যার ওপর নির্ভর করে না, তাই যেকোনো embedding ও W-তে প্রযোজ্য—একটি “golden output” তুলনার চেয়ে শক্তিশালী। পরীক্ষা অংশে softmax-এর max-বাদ মুছে দেখতে বলা হয়েছে যাতে পরীক্ষাটি সত্যিই বাগ ধরে তা নিজে দেখেন।</p></div></details>
<details class="wgba-disclose"><summary>কোন বিষয়গুলো মনে রাখব?</summary><div><ul><li>প্রতিটি মধ্যবর্তী ধাপ দৃশ্যমান রাখুন</li><li>বৈশিষ্ট্য-পরীক্ষা > একটি উদাহরণ</li><li>mask, স্থিতিশীলতা, shape—তিন সাধারণ বাগ</li><li>attention weight ≠ পূর্ণ ব্যাখ্যা</li></ul></div></details>
<details class="wgba-disclose"><summary>এখনই কোনগুলো মুখস্থ করতে হবে না?</summary><div><ul><li>বহু স্তরের attention rollout</li><li>gradient-ভিত্তিক attribution</li></ul></div></details>
<details class="wgba-disclose" open><summary>নিজে পরিবর্তন করে দেখুন</summary><div><p>একটি multi-head সংস্করণ বানান: দুটি ভিন্ন WQ/WK জোড়া দিয়ে calc দুবার চালিয়ে দুই heat map পাশাপাশি দেখান। দুই head কি ভিন্ন token-এ মনোযোগ দেয়?</p></div></details>
<section class="wgba-section" id="mistakes"><h2>সাধারণ ভুল</h2><ul><li>একটি উদাহরণের সঠিক-দেখানো আউটপুটকে প্রমাণ ধরা</li><li>heat map-এর সারি-কলাম উল্টো পড়া</li><li>mask-এর পরীক্ষায় “প্রায় ০” গ্রহণ করা</li><li>attention weight দিয়ে মডেলের সিদ্ধান্ত পুরো ব্যাখ্যা করা</li></ul></section>
<section class="wgba-section" id="check"><h2>জ্ঞান যাচাই</h2><p>নিচের 3টি প্রশ্নের উত্তর দিয়ে “জমা দিন” চাপুন। স্কোর সার্ভারে যাচাই হয়; প্রতিটি উত্তরের পর কেন সঠিক বা ভুল তা দেখাবে। লগইন থাকলে ফল আপনার অগ্রগতিতে সংরক্ষিত হয়।</p></section>
<section class="wgba-section" id="recap"><h2>সংক্ষেপে মনে রাখুন</h2><ul><li>স্বচ্ছ, পরীক্ষাযোগ্য attention</li><li>চারটি বৈশিষ্ট্য যাচাই</li><li>weight পড়া ও তার সীমা</li></ul></section>
<section class="wgba-section" id="next"><h2>পরবর্তী পাঠ</h2><p>মডেল এখন পরের token-এর বণ্টন দেয়। সেই বণ্টন থেকে কীভাবে টেক্সট বানানো হয়—sampling: <a href="/ai-academy/lesson/pretraining-next-token-loss/">Pretraining: প্রতিটি অবস্থানে Next-Token Loss</a></p></section>
<section class="wgba-section" id="sources"><h2>সূত্র ও যাচাই</h2><ul><li><a href="https://arxiv.org/abs/1706.03762" rel="noopener">Vaswani et al. — Attention Is All You Need (2017)</a></li><li><a href="https://aclanthology.org/N19-1357/" rel="noopener">Jain &amp; Wallace — Attention is not Explanation (NAACL 2019)</a></li><li><a href="https://aclanthology.org/D19-1002/" rel="noopener">Wiegreffe &amp; Pinter — Attention is not not Explanation (EMNLP 2019)</a></li></ul><p class="wgba-meta">যাচাইয়ের তারিখ: 2026-10-19; লেখক: Muhibbullah Ansary। এই পাঠের 1টি JavaScript উদাহরণ বিল্ডের সময় সাইটের একই QuickJS রানারে চালানো হয়েছে এবং প্রত্যাশিত আউটপুট মিলেছে; সংখ্যাগত ফলাফল আলাদা assertion দিয়ে (floating-point tolerance সহ) পরীক্ষিত। এই পাঠের ডেটা/উদাহরণ শেখানোর জন্য তৈরি সিন্থেটিক ডেটা—বাস্তব কোনো দোকান বা গ্রাহকের নয়। স্বাধীন বিশেষজ্ঞ রিভিউ এখনও হয়নি; ভুল পেলে যোগাযোগ পাতায় জানান।</p></section>',
